let editorImages = [];
let adminProducts = [];
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

let me=null, currentFilter='14', reminderRows=[], team=[], products=[], profile=null;
const genId=()=>(typeof crypto!=='undefined'&&typeof crypto.randomUUID==='function')?crypto.randomUUID():'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const r=Math.random()*16|0;return(c==='x'?r:(r&0x3|0x8)).toString(16);});
const money=v=>'₹'+Number(v||0).toLocaleString('en-IN');
const date=v=>v?new Intl.DateTimeFormat('en-IN',{day:'numeric',month:'short',year:'numeric'}).format(new Date(v.length===10?v+'T12:00:00Z':v)):'—';
const status=v=>`<span class="badge ${esc(v)}">${esc(v)}</span>`;
const link=(url,label,cls='')=>`<a href="${esc(url)}" data-nav class="${cls}">${label}</a>`;
const button=(label,action,id='',cls='button')=>`<button class="${cls}" data-action="${action}" data-id="${esc(id)}">${label}</button>`;
const field=(label,name,value='',type='text',extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const select=(label,name,options,value='')=>`<label>${label}<select name="${name}">${options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(l)}</option>`;}).join('')}</select></label>`;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
async function api(path,method='GET',body){const res=await fetch('/api'+path,{method,headers:{'Content-Type':'application/json',...(me?{'X-CSRF-Token':me.csrf}:{})},body:body===undefined?undefined:JSON.stringify(body)});const data=await res.json();if(!res.ok)throw Object.assign(new Error(data.error),{status:res.status});return data;}
function dialog(title,body){$('#modal').innerHTML=`<div class="dialog-head"><h2>${title}</h2><button data-action="close" aria-label="Close dialog" class="icon-button">×</button></div>${body}`;$('#modal').showModal();}
function close(){$('#modal').close();}
function formData(form){return Object.fromEntries(new FormData(form));}
function brand(){return '<span class="brand-art" role="img" aria-label="Party Bing — Balloon Decoration"><svg class="brand-mark" viewBox="530 305 440 625" aria-hidden="true"><image href="/logo.jpeg" width="1500" height="1500"/></svg><svg class="brand-wordmark" viewBox="190 985 1120 190" aria-hidden="true"><image href="/logo.jpeg" width="1500" height="1500"/></svg></span>';}
function empty(title,detail){return `<div class="empty"><span>✧</span><h3>${title}</h3><p>${detail}</p></div>`;}
async function navigate(path){history.pushState({},'',path);await render();const target=location.hash?document.getElementById(location.hash.slice(1)):null;if(target)target.scrollIntoView();else window.scrollTo(0,0);}
function intro(){let seen=false;try{seen=sessionStorage.getItem('pb_intro')==='1';sessionStorage.setItem('pb_intro','1');}catch{}if(seen||matchMedia('(prefers-reduced-motion: reduce)').matches)return;
  const el=document.createElement('div');el.className='intro';el.innerHTML=`<button class="intro-skip">Skip intro →</button><div class="intro-balloons">${Array.from({length:7},(_,i)=>`<span class="balloon b${i}"></span>`).join('')}</div><div class="confetti">${Array.from({length:18},(_,i)=>`<i class="c${i%6}">${i%3?'✦':'●'}</i>`).join('')}</div><div class="intro-logo">${brand()}<p>Make Every Celebration Magical!</p><a href="/pune-decoration">Pune locations</a></div>`;document.body.append(el);const remove=()=>el.remove();el.querySelector('button').onclick=remove;setTimeout(remove,2500);
}
function siteFooter(){return `<footer><div class="footer-info"><a class="brand" href="/" data-nav>${brand()}</a><p class="footer-tagline">Make Every Celebration Magical!</p><p class="footer-address">📍 Shop No. 11, Sai Heritage, Baner Road, near State Bank of India, Baner Gaon, Baner, Pune, Maharashtra 411045</p><p class="footer-phone">📞 WhatsApp / Call: <a href="https://wa.me/917385622113" target="_blank" rel="noopener">+91 73856 22113</a></p></div><div class="footer-links"><a href="/pune-decoration">Pune locations</a>${link('/privacy','Privacy & celebration reminders')}</div></footer>`;}
async function home(){const [featured,services]=await Promise.all([api('/products?featured=true'),api('/services')]);products=featured;$('#app').innerHTML=`<div class="site"><header class="site-header"><a href="/" data-nav class="brand">${brand()}</a><nav><a href="#services" aria-label="Browse service catalog">Services</a><a href="#collections">Featured packages</a><a href="#how">How it works</a></nav></header><main><section class="hero"><div><span class="eyebrow">LITTLE DETAILS. BIG HAPPY MOMENTS.</span><h1>Some days deserve<br>a little <em>more magic.</em></h1><p>For birthdays, new beginnings, and everything worth celebrating. We bring your happy moments to life.</p><a class="button" href="#collections">Find your celebration <span>↗</span></a><div class="hero-note"><span>✧</span> Thoughtfully styled. Beautifully remembered.</div></div><div class="hero-art" aria-label="Decorative balloon arrangement"><div class="arch"><span>let’s<br><em>celebrate</em></span></div><div class="balloon-cluster">${Array.from({length:10},(_,i)=>`<i class="balloon b${i}"></i>`).join('')}</div><span class="art-star">✧</span><div class="art-note">Made for your<br><em>kind of happy.</em></div></div></section>${serviceCatalog(services)}${budgetBar()}<section id="collections" class="collection"><div class="section-heading package-heading"><div><span class="eyebrow">A CELEBRATION FOR EVERY CHAPTER</span><h2>Featured packages</h2><p id="package-filter-summary" class="package-filter-summary" aria-live="polite">A few favourites to inspire your next celebration. Explore each service for its full collection.</p></div><a href="#services" class="button secondary">Explore all services ↗</a></div><div class="product-grid">${products.length?products.map(packageCard).join(''):empty('Featured picks coming soon','Explore a service above to browse its full decoration collection.')}</div></section><section id="how" class="how"><h2>More moments. Less planning.</h2><div><p><b>01 · Find your favourite</b><br>Choose a decoration that feels like you.</p><p><b>02 · Tell us your plans</b><br>Share the occasion, date, and details.</p><p><b>03 · Let the magic happen</b><br>Our team gets in touch to confirm everything.</p></div></section></main>${siteFooter()}</div>`;await applySeason();intro();}

const navItems=[['/admin','◫','Dashboard'],['/admin/services','✧','Services'],['/admin/products','◇','Products'],['/admin/enquiries','▤','Orders & enquiries'],['/admin/bookings','▤','Bookings'],['/admin/customers','♧','Customers'],['/admin/crm','♡','CRM & Reminders'],['/admin/media','▧','Media Library'],['/admin/content','▱','Offers & themes'],['/admin/reviews','☆','Reviews'],['/admin/settings','⚙','Settings']];
function shell(content,active='/admin/crm'){ $('#app').innerHTML=`<div class="admin-layout"><aside class="sidebar"><a href="/" data-nav class="brand">${brand()}</a><div class="workspace-label">YOUR WORKSPACE</div><nav>${navItems.map(([url,icon,label])=>link(url,`<span class="nav-icon">${icon}</span>${label}`,active===url?'active':'')).join('')}</nav><div class="sidebar-bottom"><div class="support-card"><span>✧</span><b>Every celebration<br>is a new beginning.</b><p>Keep the connection alive.</p></div><div class="admin-identity"><span class="avatar">${esc(me.name[0])}</span><div><b>${esc(me.name)}</b><small>${esc(me.role==='owner'?'Workspace owner':'Team member')}</small></div>${button('↪','logout','','icon-button')}</div></div></aside><div class="admin-body"><header class="topbar"><span>Workspace <span class="slash">/</span> <b>${esc(navItems.find(n=>n[0]===active)?.[2]||'Customers')}</b></span><div>${link('/','View website ↗','text-link')}<span class="topbar-divider"></span><span class="avatar small-avatar">${esc(me.name[0])}</span></div></header><main class="admin-main">${content}</main><footer class="admin-footer">Made for moments that matter.<span>Party Bing · Celebration workspace</span></footer></div></div>`;}
function pageHeading(kicker,title,description,actions=''){return `<div class="page-heading"><div><span class="eyebrow">${kicker}</span><h1>${title}</h1><p>${description}</p></div><div class="heading-actions">${actions}</div></div>`;}

async function crm(){const [m,rows,members]=await Promise.all([api('/admin/overview'),api('/admin/reminders?filter='+currentFilter),api('/admin/team')]);reminderRows=rows;team=members;
  const cards=[['♧','Total customers',m.total_customers,'Every connection matters'],['↻','Returning customers',m.returning_customers,'Back for more happy moments'],['✧','Upcoming celebrations',m.upcoming_celebrations,'Within the next 30 days'],['◷','Reminders due today',m.due_today,`${m.overdue} overdue follow-ups`]];
  shell(`${pageHeading('RELATIONSHIPS WORTH CELEBRATING','CRM & Reminders','Turn beautiful celebrations into lasting connections.',link('/admin/enquiries','Orders & enquiries','button')+button('↻ Refresh reminders','run-reminders','','button secondary'))}<div class="metric-grid">${cards.map(([icon,label,n,sub],i)=>`<article class="metric-card"><div><span>${label}</span><span class="metric-icon m${i}">${icon}</span></div><strong>${n}</strong><small>${sub}</small></article>`).join('')}</div><section class="crm-banner"><div class="banner-icon">✧</div><div><h3>A little thoughtfulness goes a long way.</h3><p>Remember their special day. Help make the next one even more beautiful.</p></div><div class="banner-stats"><b>${m.due_week}</b><span>due this week</span><i></i><b>${m.completed}</b><span>follow-ups completed</span></div></section><section class="panel"><div class="panel-heading"><div><h2>Celebrations on the horizon <span class="count">${rows.length}</span></h2><p>A familiar face. A special date. A reason to reconnect.</p></div><span class="timezone">◷ ${esc(m.timezone)}</span></div><div class="table-tools"><div class="filter-tabs">${[['today','Today'],['7','Next 7 days'],['14','Next 14 days'],['30','Next 30 days'],['overdue','Overdue'],['completed','Completed'],['all','All occasions']].map(([v,l])=>`<button data-action="filter" data-id="${v}" class="${currentFilter===v?'selected':''}">${l}</button>`).join('')}</div><label class="search-field"><span>⌕</span><input id="reminder-search" placeholder="Search celebrations…" aria-label="Search celebrations"></label></div><div id="reminders-table">${reminderTable(rows)}</div><div class="table-footer"><span>${rows.length} celebration${rows.length===1?'':'s'} · Filters use the follow-up due date</span><span>Consent-aware. Always personal.</span></div></section><div class="crm-bottom"><div><span class="soft-icon">♡</span><p><b>Good relationships start with respect.</b><br>Only contact customers through channels they’ve agreed to.</p></div><p>Last scheduler run<br><b>${m.last_job_run?date(m.last_job_run):'Not yet run'}</b></p></div>`);
}
function reminderTable(rows){return rows.length?`<div class="table-scroll"><table><thead><tr><th>Customer</th><th>Occasion / celebrant</th><th>Occasion date</th><th>Previous decoration</th><th>Follow-up status</th><th>Assigned to</th><th>Actions</th></tr></thead><tbody>${rows.map(r=>`<tr><td><div class="customer-cell"><span class="avatar pastel">${esc(r.full_name[0])}</span><div>${link('/admin/customers/'+r.customer_id,esc(r.full_name),'customer-name')}<small>${esc(r.normalized_phone)}</small></div></div></td><td><b class="cell-title">${esc(r.occasion_type)}</b><small>${esc(r.celebrant_name || r.relationship || r.celebrated_person || 'Customer')}</small></td><td><b class="cell-title">${date(r.occurrence_date)}</b><small class="${r.days_remaining<0?'danger-text':'warm-text'}">${r.days_remaining<0?Math.abs(r.days_remaining)+' days ago':r.days_remaining+' days to go'}</small></td><td><div class="decoration-cell"><span class="decoration-thumb ${['gold','lavender'].includes(r.product_theme)?r.product_theme:'blush'}">✧</span><span>${esc(r.product_name||'No previous decoration')}</span></div></td><td>${status(r.status)}<small>Due ${date(r.effective_due)}</small></td><td>${esc(r.assigned_admin||'Unassigned')}</td><td><div class="row-actions">${button('↗ WhatsApp','whatsapp',r.id,'whatsapp-button')}${button('•••','reminder-options',r.id,'icon-button')}</div></td></tr>`).join('')}</tbody></table></div>`:empty('Room for the next happy moment','No reminders match this filter. Try “All occasions” or save an annual occasion with consent.');}
async function customerList(q=''){const rows=await api('/admin/customers?q='+encodeURIComponent(q));shell(`${pageHeading('YOUR PEOPLE','Customers','Every celebration has a story. Keep theirs close.',button('Merge duplicates','merge','','button secondary'))}<section class="panel"><div class="panel-heading"><h2>Your customer book <span class="count">${rows.length}</span></h2><form id="customer-search" class="search-field"><input name="q" value="${esc(q)}" placeholder="Name, phone or occasion" aria-label="Search customers"><button class="text-button">Search</button></form></div>${rows.length?`<div class="table-scroll"><table><thead><tr><th>Customer</th><th>City</th><th>Bookings</th><th>Confirmed value</th><th>Last booking</th><th>Follow-up consent</th></tr></thead><tbody>${rows.map(c=>`<tr><td>${link('/admin/customers/'+c.id,esc(c.full_name),'customer-name')}<small>${esc(c.normalized_phone)}</small></td><td>${esc(c.city)}</td><td>${c.total_bookings}</td><td>${money(c.confirmed_value)}</td><td>${date(c.last_booking_date)}</td><td>${status(c.marketing_consent&&!c.marketing_opt_out_at?'granted':'denied')}</td></tr>`).join('')}</tbody></table></div>`:empty('A fresh start','Customers appear here when a decoration is booked or an enquiry is submitted.')}</section>`,'/admin/customers');}
async function customerPage(customerId){profile=await api('/admin/customers/'+customerId);const c=profile;shell(`${pageHeading('CUSTOMER PROFILE',esc(c.full_name),'A history of happy moments, and the ones still to come.',link('/admin/customers','← All customers','button secondary'))}<div class="profile-grid"><div><section class="panel profile-card"><span class="avatar large-avatar">${esc(c.full_name[0])}</span><h2>${esc(c.full_name)}</h2><p>${esc(c.city)}</p><dl><dt>Customer ID</dt><dd class="small">${esc(c.id)}</dd><dt>Phone</dt><dd>${esc(c.normalized_phone)}</dd><dt>Email</dt><dd>${esc(c.email||'Not provided')}</dd><dt>Address</dt><dd>${esc(c.address||'Not provided')}</dd><dt>First / last booking</dt><dd>${date(c.first_booking_date)} / ${date(c.last_booking_date)}</dd><dt>Bookings / confirmed value</dt><dd>${c.total_bookings} / ${money(c.confirmed_value)}</dd><dt>Marketing permission</dt><dd>${status(c.marketing_consent&&!c.marketing_opt_out_at?'granted':'denied')}</dd><dt>Contact channels</dt><dd>${c.notification_preferences.filter(p=>p.consent_status==='granted').map(p=>esc(p.channel)).join(', ')||'None'}</dd></dl>${button('Preferences & notes','profile-edit',c.id,'button secondary wide')}${button('Erase personal details','erase',c.id,'text-button danger-text')}</section><section class="panel profile-card"><h3>Important occasions</h3>${c.occasions.map(o=>`<div class="occasion-card"><b>${esc(o.occasion_type)} · ${esc(o.celebrant_name||o.relationship)}</b><p>${o.occasion_day}/${o.occasion_month} · ${o.reminder_enabled?'Active':'Disabled'}</p><small>${o.reminder_days_before} days before · Next reminder ${date(o.next_reminder_date)}</small>${button('Manage timing','occasion-edit',o.id,'text-button')}</div>`).join('')||'<p class="muted">No saved recurring occasions.</p>'}</section></div><section class="panel timeline-panel"><div class="panel-heading"><div><h2>Celebration timeline</h2><p>Bookings, follow-ups and moments remembered.</p></div><span class="soft-icon">↻</span></div><div class="timeline">${c.timeline.map(t=>`<article class="timeline-item"><div class="timeline-dot">${t.type==='booking'?'✧':t.type==='reminder'?'◷':t.type==='consent'?'♡':'↗'}</div><div><small>${date(t.date)}</small><h3>${esc(t.title)}</h3><p>${esc(t.detail)}</p>${t.booking?`<div class="timeline-booking"><span class="decoration-thumb blush">✧</span><div><b>${esc(t.booking.product_name)}</b><small>${esc(t.booking.celebrant_name||t.booking.relationship)} · ${esc(t.booking.occasion_type)}</small></div>${status(t.booking.status)}</div>`:''}</div></article>`).join('')}</div></section></div>`,'/admin/customers');}
async function bookingsPage(){const rows=await api('/admin/bookings');shell(`${pageHeading('HAPPY MOMENTS IN THE MAKING','Bookings','A clear view of every celebration, from enquiry to the final flourish.',link('/','Create a booking ↗','button'))}<section class="panel">${rows.length?`<div class="table-scroll"><table><thead><tr><th>Customer</th><th>Decoration</th><th>Event date</th><th>Amount</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(b=>`<tr><td>${link('/admin/customers/'+b.customer_id,esc(b.full_name),'customer-name')}</td><td>${esc(b.product_name)}<small>${esc(b.occasion_type)}</small></td><td>${date(b.event_date)}</td><td>${money(b.amount)}</td><td>${status(b.status)}</td><td><button class="text-button" data-action="booking-edit" data-id="${b.id}" data-status="${b.status}" data-amount="${b.amount}">Update</button></td></tr>`).join('')}</tbody></table></div>`:empty('Your next celebration is waiting','New booking requests will appear here.')}</section>`,'/admin/bookings');}
async function productsPage(serviceMode=false){const rows=await api('/admin/products');adminProducts=rows;shell(`${pageHeading('THE CELEBRATION COLLECTION',serviceMode?'Services':'Products','Manage the decorations that bring every occasion to life.',button('＋ Add product','product-add'))}<section class="panel">${rows.length?`<div class="table-scroll"><table><thead><tr><th>Decoration</th><th>Service</th><th>Price</th><th>Availability</th><th>Homepage</th><th></th></tr></thead><tbody>${rows.map(p=>`<tr><td><b>${esc(p.name)}</b><small>ID: ${esc(p.id)}</small><small>${esc(p.description)}</small></td><td>${esc(p.service)}</td><td>${priceLabel(p)}<small>${esc(p.pricing_source)}</small></td><td>${status(p.archived?'archived':'active')}</td><td><button class="text-button" data-action="product-feature" data-id="${p.id}" data-featured="${p.featured}" ${p.archived?'disabled':' '}>${p.featured?'★ Featured':'☆ Feature'}</button></td><td>${button('Edit','product-edit',p.id,'text-button')} ${button(p.archived?'Restore':'Archive','product-archive',p.id,'text-button')}<input type="hidden" id="archived-${p.id}" value="${p.archived}"></td></tr>`).join('')}</tbody></table></div>`:empty('Build your collection','Add your first decoration to start accepting bookings.')}</section>`,serviceMode?'/admin/services':'/admin/products');}
async function settingsPage(){const s=await api('/admin/settings');shell(`${pageHeading('THOUGHTFUL BY DEFAULT','Workspace settings','Set the timing and privacy defaults for your team.')}<section class="panel settings-panel"><form id="settings-form"><h2>Reminder engine</h2>${field('Business timezone','timezone',s.timezone,'text','required')}${select('February 29 policy for new occasions','leap_day_policy',[['feb28','Use February 28'],['mar1','Use March 1'],['skip','Skip non-leap years']],s.leap_day_policy)}${field('Retention review after inactivity (days)','retention_days',s.retention_days,'number','min="30" required')}<p class="muted small">Changing the default leap-day policy does not rewrite existing occasions. Review each occasion’s timing from its customer profile.</p><p class="form-error" role="alert"></p><button class="button">Save settings</button></form><hr><h3>Privacy & data retention</h3><p class="muted">Review inactive customer records before erasing their personal details. Financial booking history is retained without direct customer identifiers.</p>${button('Review records due for erasure','retention','','button secondary')}</section>`,'/admin/settings');}
async function loginPage(){ $('#app').innerHTML=`<div class="login-page"><div class="login-art"><a class="brand" href="/" data-nav>${brand()}</a><div><span class="eyebrow">THE PEOPLE BEHIND THE MAGIC</span><h1>Beautiful moments.<br><em>Lasting connections.</em></h1><p>Your celebration workspace awaits.</p></div><span class="login-spark">✧</span></div><div class="login-form"><form id="login-form"><span class="eyebrow">PARTY BING WORKSPACE</span><h1>Welcome back.</h1><p class="muted">Sign in to keep the celebrations going.</p>${field('Email address','email','','email','required autocomplete="username"')}${field('Password','password','','password','required autocomplete="current-password"')}<p class="form-error" role="alert"></p><button class="button wide">Sign in →</button><p class="small muted">Access is reserved for the Party Bing team. Ask your workspace owner for an account.</p>${link('/','← Back to celebrations','text-link')}</form></div></div>`;}
async function render(){try{const path=location.pathname;if(path==='/privacy'){ $('#app').innerHTML=`<main class="privacy"><a class="brand" href="/" data-nav>${brand()}</a><h1>Your moments. Your choice.</h1><p>We save your contact details and decoration requests to manage bookings. With your optional permission, we also save celebration details and use your selected contact channels to offer decoration ideas before recurring occasions.</p><p>Marketing consent is never required to book. We do not ask for children’s birth years or ages. Only authorized team members can access your booking history.</p><p>Use the private opt-out link shown after your booking, or ask our team to stop follow-ups, correct details or erase personal information. Financial booking records may be retained without direct identifiers. Inactive profiles are reviewed according to the workspace retention policy.</p>${link('/','← Back to Party Bing','button secondary')}</main>`;return;}
  if(path==='/opt-out'){ $('#app').innerHTML=`<main class="privacy"><h1>Your choice comes first.</h1><p>Stop future promotional celebration follow-ups from Party Bing.</p><form id="opt-out-form"><input type="hidden" name="token" value="${esc(new URLSearchParams(location.search).get('token')||'')}"><p class="form-error" role="alert"></p><button class="button">Opt out of marketing reminders</button></form></main>`;return;}
  if(path==='/packages')return await budgetPage();
  if(path.startsWith('/services/'))return await servicePage(decodeURIComponent(path.slice(10)));if(!path.startsWith('/admin'))return await home();
  if(!me){try{me=await api('/me');}catch(e){if(e.status!==401)throw e;return await loginPage();}}
  if(path==='/admin/login')return await navigate('/admin/crm');
  if(path==='/admin'||path==='/admin/crm')return await crm();
  if(path==='/admin/customers')return await customerList();
  if(path.startsWith('/admin/customers/'))return await customerPage(path.split('/').pop());
  if(path==='/admin/enquiries')return await enquiriesPage();
  if(path==='/admin/bookings')return await bookingsPage();
  if(path==='/admin/services')return await servicesPage();
  if(path==='/admin/reviews')return await reviewsPage();
  if(path==='/admin/products')return await productsPage();
  if(path==='/admin/content')return await storefrontPage();
  if(path==='/admin/settings')return await settingsPage();
  shell(`${pageHeading('PARTY BING WORKSPACE',path==='/admin/media'?'Media Library':'Website Content','This fresh workspace does not include a media or content management module.')}<section class="panel">${empty('Your CRM is ready','Manage decorations in Products and customer relationships in CRM & Reminders.')}</section>`,path);
}catch(e){if(e.status===401){me=null;return loginPage();}$('#app').innerHTML=`<main class="privacy"><h1>We couldn’t load this page.</h1><p>${esc(e.message)}</p>${button('Try again','retry')}</main>`;}}

document.addEventListener('click',async e=>{const nav=e.target.closest('a[data-nav]');if(nav){e.preventDefault();close();navigate(nav.getAttribute('href'));return;}const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action, itemId=b.dataset.id;
 try{
  if(action==='close')return close();if(action==='retry')return render();if(action==='book')return bookingDialog(itemId);
  if(action==='logout'){await api('/logout','POST',{});me=null;return navigate('/admin/login');}
  if(action==='filter'){currentFilter=itemId;return crm();}
  if(action==='run-reminders'){b.disabled=true;await api('/admin/reminders/run','POST',{});await crm();return toast('Reminders refreshed.');}
  if(action==='whatsapp'){const r=reminderRows.find(r=>r.id===itemId),w=await api('/admin/reminders/'+itemId+'/whatsapp');return dialog('A thoughtful follow-up',`<p class="muted">Review and edit your message to ${esc(r.full_name)}. Opening WhatsApp does not record contact.</p><form id="whatsapp-form"><input type="hidden" name="id" value="${itemId}"><input type="hidden" name="phone" value="${w.phone}"><label>Message<textarea name="message" rows="10" required>${esc(w.message)}</textarea></label><p class="form-error" role="alert"></p><button class="button">Open WhatsApp ↗</button></form><hr><p class="small muted">After you actually contact the customer, record the outcome separately.</p>${button('Record confirmed contact','record-contact',itemId,'button secondary')}`);}
  if(action==='reminder-options'){const r=reminderRows.find(r=>r.id===itemId);return dialog('Follow-up · '+esc(r.full_name),`<div class="action-menu">${link('/admin/customers/'+r.customer_id,'Open profile & celebration history ↗','button secondary')}${r.phone_allowed?`<a class="button secondary" href="tel:${esc(r.normalized_phone)}">Call ${esc(r.normalized_phone)}</a>`:'<p class="small muted">Phone contact is not permitted.</p>'}${button('Mark as contacted','record-contact',itemId,'button secondary')}${button('Mark as completed','complete',itemId,'button secondary')}${button('Snooze / set a follow-up date','snooze',itemId,'button secondary')}${button('Assign to a team member','assign',itemId,'button secondary')}${button('Add a follow-up note','note',itemId,'button secondary')}${button('Disable future reminders','disable',itemId,'text-button danger-text')}</div>`);}
  if(action==='record-contact')return dialog('Record actual contact',`<form id="reminder-action-form"><input type="hidden" name="id" value="${itemId}"><input type="hidden" name="action" value="contacted">${select('Contact channel','channel',[['whatsapp','WhatsApp'],['phone','Phone'],['email','Email']])}${select('Outcome','outcome',['Interested','Requested a new package','No response','Not interested','Asked to opt out'])}<label>Follow-up notes<textarea name="notes" maxlength="2000"></textarea></label><label class="check"><input type="checkbox" name="confirmed" required> I confirm I actually contacted this customer</label><p class="small muted">If they asked to opt out, update their contact preferences immediately.</p><p class="form-error" role="alert"></p><button class="button">Save contact activity</button></form>`);
  if(action==='complete'||action==='disable'){dialog(action==='complete'?'Complete this follow-up?':'Disable future reminders?',`<p>${action==='complete'?'The activity will stay in the customer’s history.':'This occasion will stop generating follow-ups. Historical activity will be preserved.'}</p><form id="reminder-action-form"><input type="hidden" name="id" value="${itemId}"><input type="hidden" name="action" value="${action==='complete'?'completed':'disable'}"><p class="form-error" role="alert"></p><button class="button">Confirm</button></form>`);return;}
  if(['snooze','assign','note'].includes(action))return dialog(action==='snooze'?'A better time to reconnect':action==='assign'?'Assign this follow-up':'Add a follow-up note',`<form id="reminder-action-form"><input type="hidden" name="id" value="${itemId}"><input type="hidden" name="action" value="${action}">${action==='snooze'?field('Follow-up date','date','','date','required'):action==='assign'?select('Team member','admin_id',[['','Unassigned'],...team.map(a=>[a.id,a.name])]):''}<label>Notes<textarea name="notes" maxlength="2000" ${action==='note'?'required':''}></textarea></label><p class="form-error" role="alert"></p><button class="button">Save follow-up</button></form>`);
  if(action==='profile-edit')return dialog('Preferences & private notes',`<form id="profile-form"><input type="hidden" name="id" value="${itemId}"><label>Decoration preferences<textarea name="preferences" maxlength="2000">${esc(profile.preferences)}</textarea></label><label>Internal admin notes<textarea name="internal_notes" maxlength="5000">${esc(profile.internal_notes)}</textarea></label><label class="check"><input type="checkbox" name="opt_out"> Customer requested no further promotional contact</label><p class="form-error" role="alert"></p><button class="button">Save preferences</button></form>`);
  if(action==='occasion-edit'){const o=profile.occasions.find(o=>o.id===itemId);return dialog('Occasion reminder timing',`<form id="occasion-form"><input type="hidden" name="id" value="${itemId}">${field('Remind this many days before','reminder_days_before',o.reminder_days_before,'number','min="0" max="365" required')}${field('Pause until (optional)','paused_until',o.paused_until||'','date')}${select('Leap-day policy','leap_day_policy',[['feb28','February 28'],['mar1','March 1'],['skip','Skip non-leap years']],o.leap_day_policy)}<p class="form-error" role="alert"></p><button class="button">Save timing</button></form>`);}
  if(action==='booking-edit')return dialog('Update booking',`<form id="booking-update-form"><input type="hidden" name="id" value="${itemId}">${select('Booking status','status',['requested','confirmed','completed','cancelled'],b.dataset.status)}${field('Final amount (₹)','amount',b.dataset.amount,'number','min="0" max="10000000" required')}<p class="form-error" role="alert"></p><button class="button">Save booking</button></form>`);
  if(action==='merge'){const rows=await api('/admin/customers');return dialog('Merge duplicate customers',`<p class="muted">Booking history and notes move to the retained profile. The stricter contact permission applies. Owner access required.</p><form id="merge-form">${select('Duplicate record to merge','source_id',rows.map(c=>[c.id,`${c.full_name} · ${c.normalized_phone}`]))}${select('Keep this customer profile','target_id',rows.map(c=>[c.id,`${c.full_name} · ${c.normalized_phone}`]))}<label class="check"><input type="checkbox" required> I verified these records belong to the same customer</label><p class="form-error" role="alert"></p><button class="button">Merge records</button></form>`);}
  if(action==='erase')return dialog('Erase personal information',`<p>Reminders will stop. Contact details, names and personal notes will be erased. Financial booking snapshots are retained. This cannot be undone. Owner access required.</p><form id="erase-form"><input type="hidden" name="id" value="${itemId}">${field('Type ERASE to confirm','confirm','','text','required pattern="ERASE"')}<p class="form-error" role="alert"></p><button class="button danger-button">Erase personal details</button></form>`);
  if(action==='retention'){const rows=await api('/admin/retention');return dialog('Retention review',rows.length?rows.map(c=>`<div class="retention-row">${link('/admin/customers/'+c.id,esc(c.full_name))}<small>Last booking ${date(c.last_booking_date)}</small>${button('Review erasure','erase',c.id,'text-button')}</div>`).join(''):'<p>No customer records are due for retention review.</p>');}
  if(action==='service-enable'||action==='service-disable'){b.disabled=true;try{await api('/admin/services','PATCH',{name:itemId,enabled:action==='service-enable'});await render();}finally{b.disabled=false;}return;}

  if(action==='service-discount')return serviceDiscountEditor(itemId);
  if(action==='enquiry-status')return enquiryStatusDialog(itemId);
  if(action==='service-add')return serviceEditor();
  if(action==='gallery')return galleryDialog(itemId);
  if(action==='reviews')return reviewDialog(itemId);
  if(action==='image-remove'){editorImages.splice(Number(itemId),1);return imagePreview();}
  if(action==='image-cover'){editorImages.unshift(...editorImages.splice(Number(itemId),1));return imagePreview();}
  if(action==='review-approve'||action==='review-hide'){await api('/admin/reviews/'+encodeURIComponent(itemId),'PATCH',{status:action==='review-approve'?'approved':'hidden'});return render();}
  if(action==='product-add')return productEditor();
  if(action==='product-edit')return productEditor(adminProducts.find(p=>p.id===itemId));
  if(action==='product-feature'){await api('/admin/products/'+itemId,'PATCH',{featured:b.dataset.featured!=='1'});await render();toast('Homepage featured packages updated.');}if(action==='product-archive'){await api('/admin/products/'+itemId,'PATCH',{archived:$('#archived-'+itemId).value==='0'});await render();toast('Collection updated. Booking history is preserved.');}
 }catch(error){toast(error.message);}finally{b.disabled=false;}
});
document.addEventListener('input',e=>{if(e.target.id==='reminder-search'){const q=e.target.value.toLowerCase();$('#reminders-table').innerHTML=reminderTable(reminderRows.filter(r=>[r.full_name,r.normalized_phone,r.occasion_type,r.celebrant_name].some(v=>(v||'').toLowerCase().includes(q))));}});
document.addEventListener('submit',async e=>{const form=e.target,formId=form.getAttribute('id');if(!formId)return;e.preventDefault();const d=formData(form),submit=form.querySelector('button[type="submit"],button:not([type])');if(submit)submit.disabled=true;const errorEl=form.querySelector('.form-error');if(errorEl)errorEl.textContent='';
 try{
  if(formId==='login-form'){const r=await api('/login','POST',d);me={...r.admin,csrf:r.csrf};return navigate('/admin/crm');}
  if(formId==='budget-filter'){const query=new URLSearchParams();if(d.under)query.set('under',d.under);if(d.service)query.set('service',d.service);return navigate('/packages?'+query);}
  if(formId==='enquiry-form')return await submitEnquiry(form,d);
  if(formId==='enquiry-status-form')await api('/admin/enquiries/'+encodeURIComponent(d.id),'PATCH',{status:d.status});
  if(formId==='opt-out-form'){await api('/opt-out','POST',d);form.innerHTML='<p>You’re opted out. Future promotional reminders are disabled. Your bookings are unaffected.</p>';return;}
  if(formId==='customer-search')return customerList(d.q);
  if(formId==='whatsapp-form'){
    await api('/admin/reminders/'+d.id+'/whatsapp');
    const a=document.createElement('a');a.href=`https://wa.me/${d.phone}?text=${encodeURIComponent(d.message)}`;a.target='_blank';a.rel='noopener noreferrer';a.click();toast('WhatsApp opened. Record contact only after you have contacted the customer.');return;
  }
  if(formId==='reminder-action-form')await api('/admin/reminders/'+d.id,'POST',{...d,confirmed:!!d.confirmed});
  if(formId==='profile-form')await api('/admin/customers/'+d.id,'PATCH',{...d,opt_out:!!d.opt_out});
  if(formId==='occasion-form')await api('/admin/occasions/'+d.id,'PATCH',{...d,reminder_days_before:Number(d.reminder_days_before)});
  if(formId==='booking-update-form')await api('/admin/bookings/'+d.id,'PATCH',{status:d.status,amount:Number(d.amount)});
  if(formId==='merge-form')await api('/admin/customers/merge','POST',d);
  if(formId==='erase-form'){await api('/admin/customers/'+d.id,'DELETE',d);close();toast('Personal details erased.');return navigate('/admin/customers');}
  if(formId==='service-discount-form')await api('/admin/services','PATCH',{name:d.name,discount_percent:Number(d.discount_percent)});
  if(formId==='service-form')await api('/admin/services','POST',d);
  if(formId==='review-form'){await api('/products/'+encodeURIComponent(d.product_id)+'/reviews','POST',{author:d.author,rating:Number(d.rating),body:d.body});close();toast('Thank you. Your review is awaiting approval.');return;}
  if(formId==='product-form')await api('/admin/products'+(d.id?'/'+encodeURIComponent(d.id):''),d.id?'PATCH':'POST',{...d,price:Number(d.price),sale_price:d.sale_price===''?null:Number(d.sale_price),trending:!!d.trending,admin_rating:d.admin_rating===''?null:Number(d.admin_rating),images:editorImages.map(i=>i.id?{id:i.id}:{data_url:i.data_url,alt:i.alt})});
  if(formId==='storefront-form')await api('/admin/storefront','PATCH',{...d,discount_percent:Number(d.discount_percent)});
  if(formId==='settings-form')await api('/admin/settings','PATCH',d);
  close();await render();toast('Saved successfully.');
 }catch(error){if(errorEl){errorEl.textContent=error.message;errorEl.setAttribute('tabindex','-1');errorEl.focus();}else toast(error.message);}finally{if(submit)submit.disabled=false;}
});
window.addEventListener('popstate',render);render();

function serviceCatalog(services) {
  const icons = { 'Birthday Decoration': '🎂', 'Anniversary Decoration': '♡', 'Baby Shower Decoration': '☀', 'Corporate Decoration': '✦' };
  return `<section id="services" class="service-catalog" aria-labelledby="service-catalog-title">
    <div class="section-heading"><div><span class="eyebrow">LET’S PLAN YOUR NEXT CELEBRATION</span><h2 id="service-catalog-title">Service catalog</h2><p>Choose your occasion to browse its decoration collection.</p></div></div>
    <div class="service-grid">${services.map(service => {
      return link('/services/'+encodeURIComponent(service.slug),`<span class="service-icon" aria-hidden="true">${icons[service.name] || '✧'}</span><strong>${esc(service.name)}</strong><span class="service-meta" ${service.package_count?`aria-label="${service.package_count} packages, starting from ${money(service.starting_price)}"`:''}>${service.package_count?`<span class="service-meta-full">${service.package_count} packages · From ${money(service.starting_price)}</span><span class="service-meta-short" aria-hidden="true">${service.package_count} pkgs · Starts ${money(service.starting_price)}</span>`:'Packages coming soon'}</span><span class="service-cta">Explore packages ↗</span>`,'service-card');
    }).join('') || '<p>Our service collection is being prepared. Please check back soon.</p>'}</div>
  </section>`;
}

function packageCard(p) {
  const theme=['blush','gold','lavender'].includes(p.theme)?p.theme:'blush';
  const art=p.images?.length?`<div class="product-photo"><img src="${esc(p.images[0].url)}" alt="${esc(p.images[0].alt||p.name)}" loading="lazy" width="640" height="480">${button('View '+p.images.length+' photo'+(p.images.length===1?'':'s'),'gallery',p.id,'gallery-button')}</div>`:`<div class="product-art ${theme}"><div class="mini-arch">${esc(p.service)}</div><span class="mini-balloons" aria-hidden="true">●<br>● ●<br>● ● ●</span><span class="product-spark" aria-hidden="true">✧</span></div>`;
  return `<article class="product-card"><div class="product-visual">${art}${productBadges(p)}</div><div class="product-info"><h3>${esc(p.name)}</h3>${packageDetails(p)}<div class="product-purchase">${priceLabel(p)}${button('Order <span class="order-arrow" aria-hidden="true">↗</span>','book',p.id,'order-button')}</div></div></article>`;
}

async function servicePage(slug) {
  const requested = new URLSearchParams(location.search).get('page') || '1';
  let result;
  try { result = await api('/catalog?service='+encodeURIComponent(slug)+'&page='+encodeURIComponent(requested)); }
  catch(error) {
    if(error.status!==404) throw error;
    $('#app').innerHTML=`<main class="privacy"><h1>Service not found</h1><p>This service may no longer be available.</p>${link('/#services','Explore our services','button')}</main>`;
    return;
  }
  products=result.items;
  const {service,page,page_count,total,page_size}=result;
  const url=n=>'/services/'+encodeURIComponent(service.slug)+'?page='+n;
  const pages=[...new Set([1,page-1,page,page+1,page_count])].filter(n=>n>=1&&n<=page_count).sort((a,b)=>a-b);
  let previous=0;
  const pageLinks=pages.map(n=>{
    const gap=previous && n>previous+1 ? '<span aria-hidden="true">…</span>' : '';
    previous=n;
    return gap+(n===page?`<span class="page-current" aria-current="page">${n}</span>`:link(url(n),String(n),'page-link'));
  }).join('');
  $('#app').innerHTML=`<div class="site"><header class="site-header">${link('/',brand(),'brand')}<nav>${link('/#services','All services')}${link('/#collections','Featured packages')}</nav></header><main class="service-page"><nav class="breadcrumbs" aria-label="Breadcrumb">${link('/','Home')}<span>/</span>${link('/#services','Services')}<span>/</span><span aria-current="page">${esc(service.name)}</span></nav><section class="service-page-heading"><span class="eyebrow">A LITTLE MAGIC FOR YOUR SPECIAL DAY</span><h1>${esc(service.name)}</h1><p>${total?`Explore ${total} decoration package${total===1?'':'s'}, starting from ${money(service.starting_price)}. Choose your favourite and tell us about your celebration.`:esc(service.description||'We’re preparing this service’s decoration collection. Check back soon.')}</p></section>${budgetBar(service.slug)}<div class="catalog-result-summary"><p>Showing ${total?(page-1)*page_size+1:0}–${Math.min(page*page_size,total)} of ${total} packages</p>${link('/#services','← Browse other services','text-link')}</div><div class="product-grid">${products.length?products.map(packageCard).join(''):empty('Packages coming soon','Explore another service while we prepare this collection.')}</div>${page_count>1?`<nav class="catalog-pagination" aria-label="Package pages">${page>1?link(url(page-1),'← Previous','button secondary'):'<span></span>'}<div>${pageLinks}</div>${page<page_count?link(url(page+1),'Next →','button secondary'):'<span></span>'}</nav>`:''}</main>${siteFooter()}</div>`;
  await applySeason();
}

function priceLabel(p) {
  return `<span class="package-price"><strong>${money(p.final_price ?? p.price)}</strong>${p.final_price<p.price?` <del>${money(p.price)}</del><span class="offer-tag">${p.sale_price!=null?'Offer price':p.effective_discount+'% off'}</span>`:''}</span>`;
}
function packageDetails(p) {
  const setup={wall:'Wall mount',stand:'Stand mount',both:'Wall + stand mount',unspecified:'Setup to be confirmed'};
  return `<span class="setup-tag">${setup[p.setup_type]||setup.unspecified}</span><details class="package-inclusions"><summary>Details & inclusions</summary><p>${esc(p.description)}</p><ul>${(p.inclusions||p.description).split('\n').filter(x=>x.trim()).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details>`;
}

function seasonOptions() {
  return [['default','Everyday Party Bing','Our original celebration style.'],['new-year','New Year','Midnight blue accents for new beginnings.'],['wedding-season','Wedding season','Rose accents for your next chapter together.'],['janmashtami','Janmashtami','Peacock teal accents for joyful festivities.'],['diwali','Diwali','Amber accents for the festival of lights.']];
}
async function storefrontPage() {
  const config=await api('/admin/storefront');
  shell(`${pageHeading('YOUR STOREFRONT','Offers & themes','Set an offer for the whole collection and choose the season’s look.')}<form id="storefront-form" class="storefront-form"><section class="panel offer-settings"><h2>Store-wide discount</h2>${field('Discount on all products (%)','discount_percent',config.discount_percent,'number','required min="0" max="100" step="1"')}<p class="muted">Use 0 to turn off the offer. This percentage applies to original prices and overrides product discount prices. An active service offer takes priority over this offer. Offers never stack; existing bookings keep their saved price.</p>${link('/admin/products','Manage individual product discounts →')}</section><section class="panel offer-settings"><fieldset><legend>Seasonal theme</legend><p class="muted">Choose one theme, then save to make it live. Themes change the storefront appearance and message; they do not create discounts.</p><div class="season-options">${seasonOptions().map(([value,label,description])=>`<label class="season-option" data-season="${value}"><input type="radio" name="season" value="${value}" ${config.season===value?'checked':''}><span class="season-swatch" aria-hidden="true">✧</span><span><strong>${label}</strong><small>${description}</small></span></label>`).join('')}</div></fieldset></section><p class="form-error" role="alert"></p><div class="storefront-save"><button class="button">Save storefront settings</button>${link('/','View storefront ↗','text-link')}</div></form>`,'/admin/content');
}
async function applySeason() {
  const config=await api('/site');
  const site=$('.site');if(!site)return;
  site.dataset.season=config.season;
  const messages={'new-year':'New year. New memories.','wedding-season':'For your happily ever after.','janmashtami':'Celebrate the joy of Janmashtami.','diwali':'Make room for a little more light.'};
  if(messages[config.season]) {
    const heading=site.querySelector('.hero h1');if(heading)heading.textContent=messages[config.season];
    const eyebrow=site.querySelector('.hero .eyebrow, .service-page-heading .eyebrow');
    if(eyebrow)eyebrow.textContent=seasonOptions().find(x=>x[0]===config.season)[1]+' celebrations';
  }
}

async function servicesPage(){
  const services=await api('/admin/services');
  shell(`${pageHeading('THE CELEBRATION COLLECTION','Services','Disabled services and their products are hidden from customers. All product details and photos stay saved.',button('Add service','service-add'))}<section class="panel"><div class="table-scroll"><table><thead><tr><th>Service</th><th>Products</th><th>Visibility</th><th>Category discount</th><th>Customer page</th></tr></thead><tbody>${services.map(s=>`<tr><td><b>${esc(s.name)}</b><small>${esc(s.description)}</small></td><td>${s.package_count}</td><td><span class="service-status">${s.enabled?'Enabled':'Disabled'}</span> ${button(s.enabled?'Disable':'Enable',s.enabled?'service-disable':'service-enable',s.name,'text-button')}</td><td>${s.discount_percent?s.discount_percent+'% off original prices':'Off'} ${button('Edit offer','service-discount',s.name,'text-button')}</td><td>${s.enabled?link('/services/'+encodeURIComponent(s.slug),'View service ↗'):'<span class="muted">Hidden from customers</span>'}</td></tr>`).join('')}</tbody></table></div>${services.length?'':empty('Add your first service','Services appear in the product form’s dropdown.')}</section>`,'/admin/services');
}
function serviceEditor(){dialog('Add service',`<form id="service-form">${field('Service name *','name','','text','required maxlength="100" placeholder="For example: Housewarming Decoration"')}<label>Description (optional)<textarea name="description" maxlength="1000"></textarea></label><p class="muted small">This service will appear in the service catalog and product dropdown. Its page will show “Packages coming soon” until you add products.</p><p class="form-error" role="alert"></p><button class="button">Create service</button></form>`);}
async function productEditor(p={}){
 const services=await api('/admin/services');
 if(!services.length){dialog('Add a service first',`<p>Create a service before adding a product.</p>${link('/admin/services','Manage services','button')}`);return;}
 editorImages=(p.images||[]).map(i=>({...i}));
 dialog(p.id?'Edit product':'Add product',`<form id="product-form" class="product-editor"><input type="hidden" name="id" value="${esc(p.id||'')}"><fieldset><legend>Product details</legend>${field('Product ID','product_id',p.id||'','text',p.id?'readonly':'maxlength="64" pattern="[a-zA-Z0-9_-]{3,64}" placeholder="Auto-generated if left blank"')}${field('Product name *','name',p.name||'','text','required maxlength="150"')}${select('Service *','service',[['','Select a service'],...services.map(s=>[s.name,s.name+(s.enabled?'':' (disabled)')])],p.service||'')}<label>Description *<textarea name="description" required maxlength="1000">${esc(p.description||'')}</textarea></label><label>What’s included *<textarea name="inclusions" required maxlength="3000" rows="4" placeholder="List each included item on a new line">${esc(p.inclusions||p.description||'')}</textarea></label>${select('Mount type *','setup_type',[['','Select mount type'],['wall','Wall mount'],['stand','Stand mount'],['both','Wall + stand mount']],p.setup_type||'')}</fieldset><fieldset><legend>Pricing</legend><div class="form-grid">${field('Original price (₹) *','price',p.price??'','number','required min="0" max="10000000" step="1"')}${field('Discount price (₹, optional)','sale_price',p.sale_price??'','number','min="0" max="10000000" step="1" placeholder="Leave blank to use original price"')}</div><p class="small muted">This is the default product price. Active service or store-wide offers override it, calculated from the original price. Priority: service offer → store-wide offer → product discount price → original price. Offers do not stack.</p></fieldset><fieldset><legend>Product badges</legend><label class="check"><input type="checkbox" name="trending" ${p.trending?'checked':''}> Mark as Trending</label>${field('Admin rating out of 5 (optional)','admin_rating',p.admin_rating??'','number','min="1" max="5" step="0.1" placeholder="For example: 4.5"')}<p class="small muted">Shown at the top-left as a star rating. Leave blank to show the approved customer average, or “Not rated” when there are no reviews. Trending appears at the top-right.</p></fieldset><fieldset><legend>Product images</legend><p class="small muted">Up to 6 JPG, PNG or WebP images, 2 MB each. The first image is the cover. Changes apply when you save the product.</p><label>Add images<input id="product-upload" type="file" accept="image/jpeg,image/png,image/webp" multiple></label><div id="image-preview" class="image-preview"></div>${select('Artwork when no photo is uploaded','theme',['blush','gold','lavender'],p.theme||'blush')}</fieldset><p class="small muted">Reviews are submitted by customers and managed in Reviews. Existing bookings retain their saved details and price.</p><p class="form-error" role="alert" tabindex="-1"></p><button class="button" type="submit">${p.id?'Save product':'Add product'}</button></form>`);
 $('#product-form select[name="service"]').required=true;$('#product-form select[name="setup_type"]').required=true;imagePreview();
}
function imagePreview(){
 const target=$('#image-preview');if(!target)return;
 target.innerHTML=editorImages.map((i,n)=>`<div class="image-preview-item"><img src="${esc(i.url||i.data_url)}" alt="${esc(i.alt||'Product photo '+(n+1))}"><span>${n===0?'Cover image':'Image '+(n+1)}</span><div>${n?`<button type="button" class="text-button" data-action="image-cover" data-id="${n}">Make cover</button>`:''}<button type="button" class="text-button" data-action="image-remove" data-id="${n}" aria-label="Remove image ${n+1}">Remove</button></div></div>`).join('');
}
document.addEventListener('change',async e=>{
 if(e.target.id!=='product-upload')return;
 const input=e.target,form=input.closest('form'),error=form.querySelector('.form-error'),submit=form.querySelector('[type="submit"]');
 submit.disabled=true;error.textContent='';
 try{
  const files=[...input.files];if(files.length+editorImages.length>6)throw Error('Choose up to 6 images in total. Remove an image before adding more.');
  if(files.some(f=>!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>2*1024*1024))throw Error('Use JPG, PNG or WebP images up to 2 MB each.');
  const images=await Promise.all(files.map(file=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve({data_url:reader.result,alt:form.elements.name.value.trim()||'Decoration product'});reader.onerror=()=>reject(Error('Could not read this image. Please select it again.'));reader.readAsDataURL(file);})));if(!form.isConnected)return;
  editorImages.push(...images);imagePreview();
 }catch(e){error.textContent=e.message;error.focus();}finally{input.value='';submit.disabled=false;}
});
function galleryDialog(id){const p=products.find(p=>p.id===id);if(!p)return;dialog(esc(p.name),`<div class="product-gallery">${p.images.map((i,n)=>`<figure><img src="${esc(i.url)}" alt="${esc(i.alt||p.name)}"><figcaption>Image ${n+1} of ${p.images.length}</figcaption></figure>`).join('')}</div>`);}
async function reviewDialog(id){
 const p=products.find(p=>p.id===id);if(!p)return;const reviews=await api('/products/'+encodeURIComponent(id)+'/reviews');
 dialog('Reviews · '+esc(p.name),`<div class="review-list">${reviews.length?reviews.map(r=>`<article class="review-entry"><b>${esc(r.author)}</b><span aria-label="${r.rating} out of 5 stars">${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</span><p>${esc(r.body)}</p><small>${date(r.created_at)}</small></article>`).join(''):'<p>No reviews yet. Share your experience with this decoration.</p>'}</div><form id="review-form"><h3>Write a review</h3><input type="hidden" name="product_id" value="${esc(id)}">${field('Your display name *','author','','text','required maxlength="100"')}${select('Rating *','rating',[['','Select a rating'],[5,'5 — Excellent'],[4,'4 — Good'],[3,'3 — Average'],[2,'2 — Fair'],[1,'1 — Poor']])}<label>Your review *<textarea name="body" required maxlength="2000" rows="4"></textarea></label><p class="small muted">Your display name, rating and review will be public after admin approval. Please describe your own experience and avoid sharing contact details.</p><p class="form-error" role="alert"></p><button class="button">Submit review</button></form>`);$('#review-form select').required=true;
}
async function reviewsPage(){
 const reviews=await api('/admin/reviews');
 shell(`${pageHeading('CUSTOMER FEEDBACK','Reviews','Approve customer submissions to publish them. Only approved reviews contribute to product ratings.')}<section class="panel">${reviews.length?`<div class="table-scroll"><table><thead><tr><th>Product / reviewer</th><th>Rating / review</th><th>Status</th><th>Actions</th></tr></thead><tbody>${reviews.map(r=>`<tr><td><b>${esc(r.product_name)}</b><small>${esc(r.author)} · ${date(r.created_at)}</small></td><td><b>${r.rating}/5</b><p class="review-body">${esc(r.body)}</p></td><td>${status(r.status)}</td><td>${r.status!=='approved'?button('Approve','review-approve',r.id,'text-button'):''} ${r.status!=='hidden'?button('Hide','review-hide',r.id,'text-button'):''}</td></tr>`).join('')}</tbody></table></div>`:empty('No reviews yet','Customer reviews will appear here for approval.')}</section>`,'/admin/reviews');
}

function productBadges(p){
 const score=p.admin_rating??p.rating;
 const label=score!=null?'Rating':'Not rated';
 return `<span class="product-corner-rating" aria-label="${label}${score!=null?' '+score+' out of 5':''}"><b>${score!=null?'★ '+Number(score).toFixed(1)+'/5':'☆ Not rated'}</b></span>${p.trending?'<span class="product-corner-trending">Trending</span>':''}`;
}
async function serviceDiscountEditor(name){
 const service=(await api('/admin/services')).find(s=>s.name===name);if(!service)return;
 dialog('Service-wide discount',`<form id="service-discount-form"><input type="hidden" name="name" value="${esc(service.name)}"><h3>${esc(service.name)}</h3>${field('Discount on this service (%)','discount_percent',service.discount_percent,'number','required min="0" max="100" step="1"')}<p class="muted">Applied to every product’s original price in this service. Overrides both the store-wide offer and product discount prices. Use 0 to turn this override off and return to store-wide or product pricing.</p><p class="form-error" role="alert"></p><button class="button">Save service offer</button></form>`);
}

async function bookingDialog(productId){
 const p=products.find(p=>p.id===productId);if(!p)return;
 const {items}=await api('/addons');
 const occasion=p.service.replace(/\s*Decoration\s*$/i,'');
 dialog('Make it your celebration',`<form id="enquiry-form" class="enquiry-form"><input type="hidden" name="product_id" value="${esc(p.id)}"><input type="hidden" name="expected_price" value="${p.final_price}"><input type="hidden" name="request_id" value="${genId()}"><div class="order-product"><span class="eyebrow">YOUR SELECTED DECORATION</span><h3>${esc(p.name)}</h3><p>${esc(p.service)} · ${money(p.final_price)}</p><small>Decoration price only. Add-ons are quoted separately.</small></div><div class="form-grid">${field('Your phone number *','phone','','tel','required maxlength="30" autocomplete="tel" placeholder="+91 98765 43210"')}${field('Occasion *','occasion',occasion,'text','required maxlength="100" placeholder="Birthday, anniversary…"')}</div><details class="addon-dropdown"><summary>Add-ons <span class="addon-count">Optional</span></summary><div class="addon-dropdown-body"><fieldset class="addon-fieldset" aria-label="Optional add-ons"><div class="addon-options">${items.map(name=>`<label class="addon-option"><input type="checkbox" name="addons" value="${esc(name)}">${addonIcon(name)}<span>${esc(name)}</span></label>`).join('')}</div></fieldset><label>Anything else? (optional)<input type="text" name="custom_addon" maxlength="1000" placeholder="Other add-on or special request"></label></div></details><p class="small muted">Your enquiry is saved for follow-up. Tap Send in WhatsApp to message us. Our team confirms availability and the final quote.</p><p class="form-error" role="alert" tabindex="-1"></p><button type="submit" class="button wide">Send on WhatsApp ↗</button></form>`);
}
document.addEventListener('input',event=>{
 const form=event.target.closest('#enquiry-form');if(!form)return;
 const count=form.querySelectorAll('input[name="addons"]:checked').length;
 const custom=form.querySelector('[name="custom_addon"]').value.trim();
 form.querySelector('.addon-count').textContent=[count?count+' selected':'',custom?'Custom request':''].filter(Boolean).join(' · ')||'Optional';
});
async function submitEnquiry(form,d){
 const addons=new FormData(form).getAll('addons');
 let popup=null;
 try{popup=window.open('about:blank','_blank');if(popup)popup.opener=null;}catch{}
 let result;
 try{result=await api('/enquiries','POST',{...d,addons,expected_price:Number(d.expected_price)});}catch(error){if(popup)popup.close();throw error;}
 dialog('Your enquiry is saved',`<p>Your product, occasion and add-on choices are saved with our team.</p><p class="small">Reference: ${esc(result.id)}</p><p>Send the prepared message in WhatsApp to continue. If it didn’t open, use the button below.</p><a href="${esc(result.whatsapp_url)}" target="_blank" rel="noopener noreferrer" class="button">Open WhatsApp ↗</a><details class="package-inclusions"><summary>View your enquiry</summary><p class="enquiry-message">${esc(result.message)}</p></details>`);
 if(popup&&!popup.closed){
   popup.location.replace(result.whatsapp_url);
 } else {
   window.location.href=result.whatsapp_url;
 }
}
let enquiryRows=[];
async function enquiriesPage(){
 enquiryRows=await api('/admin/enquiries');
 shell(`${pageHeading('YOUR CELEBRATION REQUESTS','Orders & enquiries','The same details prepared for WhatsApp, saved here before the customer opens it. New enquiries are not confirmed bookings.')}<section class="panel">${enquiryRows.length?`<div class="table-scroll"><table><thead><tr><th>Customer / occasion</th><th>Product</th><th>Add-ons & requests</th><th>Status</th><th></th></tr></thead><tbody>${enquiryRows.map(e=>`<tr><td>${link('/admin/customers/'+e.customer_id,esc(e.phone))}<small>${esc(e.occasion)} · ${date(e.created_at)}</small></td><td><b>${esc(e.product_name)}</b><small>${esc(e.service_name)}</small><span>${money(e.amount)} decoration only</span></td><td><p class="review-body">${esc(e.addons.join(', ')||'No add-ons')}</p>${e.custom_addon?`<p class="review-body">Other: ${esc(e.custom_addon)}</p>`:''}<details><summary>Full enquiry</summary><p class="enquiry-message">${esc(e.message)}</p></details></td><td>${status(e.status)}</td><td>${button('Update status','enquiry-status',e.id,'text-button')}</td></tr>`).join('')}</tbody></table></div>`:empty('No enquiries yet','Requests from the storefront will appear here, with phone, occasion, product and add-ons.')}</section>`,'/admin/enquiries');
}
function enquiryStatusDialog(id){const e=enquiryRows.find(e=>e.id===id);if(!e)return;dialog('Update enquiry',`<form id="enquiry-status-form"><input type="hidden" name="id" value="${esc(id)}"><p>${esc(e.product_name)} · ${esc(e.phone)}</p>${select('Status','status',['new','contacted','confirmed','cancelled'],e.status)}<p class="small muted">Only mark confirmed after agreeing availability and the final quote with the customer.</p><p class="form-error" role="alert"></p><button class="button">Save status</button></form>`);}

