function budgetBar(service=''){
 const options=[1999,2999,3999,4999,7999,9999];
 return `<nav class="budget-bar" aria-label="Shop by budget"><strong>Shop by budget</strong><div>${options.map(value=>link('/packages?under='+value+(service?'&service='+encodeURIComponent(service):''),'Under '+money(value),'budget-link')).join('')}${link('/packages'+(service?'?service='+encodeURIComponent(service):''),'All prices','budget-link')}</div></nav>`;
}
async function budgetPage(){
 const query=new URLSearchParams(location.search);
 const [result,services]=await Promise.all([api('/browse?'+query),api('/services')]);products=result.items;
 const title=result.under?'Decorations under '+money(result.under):'All decoration packages';
 const pageUrl=page=>{const next=new URLSearchParams();if(result.under)next.set('under',result.under);if(result.service)next.set('service',result.service.slug);next.set('page',page);return '/packages?'+next;};
 const budgets=[...new Set([1999,2999,3999,4999,7999,9999,...(result.under?[result.under]:[])])].sort((a,b)=>a-b);
 $('#app').innerHTML=`<div class="site"><header class="site-header">${link('/',brand(),'brand')}<nav>${link('/#services','All services')}${link('/#collections','Featured packages')}</nav></header><main class="service-page"><nav class="breadcrumbs" aria-label="Breadcrumb">${link('/','Home')}<span>/</span><span aria-current="page">Shop by budget</span></nav><section class="budget-heading"><h1>${title}</h1><p>Find your celebration at a price that fits. Prices include current decoration offers; add-ons are quoted separately.</p></section><form id="budget-filter" class="budget-filter">${select('Budget','under',[['','All prices'],...budgets.map(n=>[n,'Under '+money(n)])],result.under||'')}${select('Service / category','service',[['','All services'],...services.map(s=>[s.slug,s.name])],result.service?.slug||'')}<button class="button" type="submit">Apply filters</button>${link('/packages','Clear filters','text-link')}</form><div class="catalog-result-summary"><p>${result.total?`Showing ${(result.page-1)*result.page_size+1}–${Math.min(result.page*result.page_size,result.total)} of ${result.total} packages`:'No matching packages'}${result.service?' · '+esc(result.service.name):''}</p><span class="muted small">Lowest price first</span></div>${products.length?`<div class="product-grid">${products.map(packageCard).join('')}</div>`:`<section class="panel budget-empty">${empty('No packages in this budget yet','Choose a higher budget or another service to see more decorations.')}${link('/packages','Browse all packages','button secondary')}</section>`}${result.page_count>1?`<nav class="catalog-pagination" aria-label="Package pages">${result.page>1?link(pageUrl(result.page-1),'← Previous','button secondary'):'<span></span>'}<span>Page ${result.page} of ${result.page_count}</span>${result.page<result.page_count?link(pageUrl(result.page+1),'Next →','button secondary'):'<span></span>'}</nav>`:''}</main>${siteFooter()}</div>`;
 await applySeason();
}
